"""Installer decisions based on active grants in a selected repository."""

from .grants import _normalize_namespace, _validate_owner
from .matching import namespace_matches

__all__ = ["SecurityPolicy"]


class SecurityPolicy:
    """Require a project owner to hold a grant for a configured namespace."""

    def __init__(self, namespaces, owner):
        self.owner = _validate_owner(owner)
        self.namespaces = tuple(sorted({_normalize_namespace(name)
                                        for name in namespaces}))

    def allows(self, project, index):
        """Check the project against grants on this repository only."""
        project = _normalize_namespace(project)
        if (not index.supports_namespaces
                or index.project_owner(project) != self.owner):
            return False
        for namespace in self.namespaces:
            grant = index.store.get(namespace)
            if (grant is not None and grant.owner == self.owner
                    and namespace_matches(namespace, project)):
                return True
        return False

    def evaluate(self, projects, index):
        """Map normalized project names to their individual decisions."""
        return {_normalize_namespace(project): self.allows(project, index)
                for project in projects}

