from dataclasses import dataclass

from .matching import namespace_matches
from .normalize import hyphen_depth, is_valid_namespace, normalize_name

__all__ = [
    "DEFAULT_DEPTH_LIMIT", "Grant", "GrantStore", "GrantError",
    "InvalidNamespaceError", "OverlapError", "DepthLimitError",
    "UnknownGrantError", "grants_overlap",
]

DEFAULT_DEPTH_LIMIT = 3


class GrantError(ValueError):
    """Base exception for invalid grant operations."""


class InvalidNamespaceError(GrantError):
    """A name does not have the package namespace format."""


class OverlapError(GrantError):
    """A grant overlaps a grant belonging to another owner."""


class DepthLimitError(GrantError):
    """A namespace exceeds the store's depth limit."""


class UnknownGrantError(GrantError):
    """An operation requires a grant that does not exist."""


def _normalize_namespace(name):
    if not is_valid_namespace(name):
        raise InvalidNamespaceError(f"invalid namespace: {name!r}")
    return normalize_name(name)


def _validate_owner(owner):
    if not isinstance(owner, str) or not owner.strip():
        raise GrantError("owner must be a non-empty string")
    return owner


def grants_overlap(first, second):
    """Return whether two normalized namespace prefixes overlap."""
    first = normalize_name(first) + "-"
    second = normalize_name(second) + "-"
    return first.startswith(second) or second.startswith(first)


@dataclass(frozen=True)
class Grant:
    """An immutable normalized namespace and its owner."""

    name: str
    owner: str

    def __post_init__(self):
        object.__setattr__(self, "name", _normalize_namespace(self.name))
        _validate_owner(self.owner)


class GrantStore:
    """Hold active grants for one repository.

    depth_limit is the maximum normalized hyphen count, or None for no limit.
    Iteration yields grants sorted by name.
    """

    def __init__(self, depth_limit=DEFAULT_DEPTH_LIMIT):
        if depth_limit is not None and (
            not isinstance(depth_limit, int) or depth_limit < 0
        ):
            raise ValueError("depth_limit must be a non-negative integer or None")
        self.depth_limit = depth_limit
        self._grants = {}

    def __len__(self):
        return len(self._grants)

    def __contains__(self, namespace):
        return (is_valid_namespace(namespace)
                and normalize_name(namespace) in self._grants)

    def __iter__(self):
        return (self._grants[name] for name in self.namespaces())

    def _check_overlap(self, name, owner):
        for grant in self:
            if grant.owner != owner and grants_overlap(name, grant.name):
                raise OverlapError(
                    f"{name!r} overlaps the grant {grant.name!r} "
                    f"held by {grant.owner!r}"
                )

    def reserve(self, namespace, owner):
        """Reserve a namespace, allowing overlap only with the same owner."""
        grant = Grant(namespace, owner)
        if (self.depth_limit is not None
                and hyphen_depth(grant.name) > self.depth_limit):
            raise DepthLimitError(
                f"{grant.name!r} exceeds depth limit {self.depth_limit}"
            )
        self._check_overlap(grant.name, grant.owner)
        self._grants[grant.name] = grant
        return grant

    def transfer(self, namespace, owner):
        """Transfer a grant, preserving ownership of overlapping grants."""
        grant = self.get(namespace)
        if grant is None:
            raise UnknownGrantError(f"unknown grant: {namespace!r}")
        owner = _validate_owner(owner)
        for other in self:
            if (other.name != grant.name and other.owner != owner
                    and grants_overlap(grant.name, other.name)):
                raise OverlapError(
                    f"{grant.name!r} overlaps the grant {other.name!r} "
                    f"held by {other.owner!r}"
                )
        replacement = Grant(grant.name, owner)
        self._grants[grant.name] = replacement
        return replacement

    def remove(self, namespace):
        """Withdraw a grant; raise UnknownGrantError if it is absent."""
        name = _normalize_namespace(namespace)
        try:
            return self._grants.pop(name)
        except KeyError:
            raise UnknownGrantError(f"unknown grant: {name!r}") from None

    def get(self, namespace):
        """Return the exact grant, or None when it is ungranted."""
        return self._grants.get(_normalize_namespace(namespace))

    def namespaces(self):
        """Return all granted names in sorted order."""
        return sorted(self._grants)

    def matching(self, project):
        """Return matching grants sorted by namespace name."""
        project = _normalize_namespace(project)
        return [grant for grant in self
                if namespace_matches(grant.name, project)]

    def parent(self, namespace):
        """Return the nearest granted ancestor's name, or None."""
        name = _normalize_namespace(namespace)
        if name not in self._grants:
            return None
        ancestor, separator, _ = name.rpartition("-")
        while separator:
            if ancestor in self._grants:
                return ancestor
            ancestor, separator, _ = ancestor.rpartition("-")
        return None

    def children(self, namespace):
        """Return sorted direct granted children of an active namespace."""
        name = _normalize_namespace(namespace)
        if name not in self._grants:
            return []
        return [child for child in self.namespaces()
                if self.parent(child) == name]

