"""Command-line management of a local JSON repository store."""

import argparse
import json
import os
from pathlib import Path
import sys
import tempfile

from .grants import _normalize_namespace, _validate_owner
from .metadata import RepositoryIndex
from .uploads import UploadConflictError, authorize_upload

__all__ = ["CONFLICT_EXIT", "main"]

CONFLICT_EXIT = 3


def _load(path):
    index = RepositoryIndex()
    try:
        with path.open(encoding="utf-8") as stream:
            document = json.load(stream)
    except FileNotFoundError:
        return index
    except (ValueError, UnicodeError) as exc:
        raise ValueError(f"corrupt store: {exc}") from exc

    try:
        if (not isinstance(document, dict)
                or set(document) != {"grants", "projects", "grandfathered"}
                or not isinstance(document["grants"], dict)
                or not isinstance(document["projects"], dict)
                or not isinstance(document["grandfathered"], list)):
            raise ValueError("expected grants, projects and grandfathered fields")
        # Existing projects can predate grants. Loading is not a new upload.
        for project, owner in document["projects"].items():
            if index.project_owner(project) is not None:
                raise ValueError(f"duplicate normalized project: {project!r}")
            index.register_project(project, owner)
        for project in document["grandfathered"]:
            index.grandfathered.add(project)
        for namespace, owner in document["grants"].items():
            if index.store.get(namespace) is not None:
                raise ValueError(f"duplicate normalized grant: {namespace!r}")
            index.store.reserve(namespace, owner)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"corrupt store: {exc}") from exc
    return index


def _document(index):
    return {"grants": {grant.name: grant.owner for grant in index.store},
            "projects": index.projects(),
            "grandfathered": index.grandfathered.projects()}


def _save(path, index):
    # Replace only after writing a complete document in the same directory.
    temporary = None
    try:
        with tempfile.NamedTemporaryFile(
            mode="w", encoding="utf-8", dir=path.parent,
            prefix=f".{path.name}.", delete=False,
        ) as stream:
            temporary = stream.name
            json.dump(_document(index), stream, indent=2, sort_keys=True)
            stream.write("\n")
        os.replace(temporary, path)
    finally:
        if temporary is not None and os.path.exists(temporary):
            os.unlink(temporary)


def _common_options(parser, *, defaults=False):
    parser.add_argument(
        "--store", metavar="FILE", type=Path,
        default=Path("packagenamespaces.json") if defaults else argparse.SUPPRESS,
        help="JSON state file (default: packagenamespaces.json)",
    )
    parser.add_argument(
        "--json", action="store_true",
        default=False if defaults else argparse.SUPPRESS,
        help="print the result as JSON",
    )


def _parser():
    parser = argparse.ArgumentParser(
        prog="python -m packagenamespaces",
        description="Manage repository-local PEP 752 namespace grants.",
    )
    _common_options(parser, defaults=True)
    parser.add_argument("--owner", help="grant holder or project owner")
    parser.add_argument("--project", help="select one project for dump")
    commands = parser.add_subparsers(dest="command", required=True)
    descriptions = {
        "reserve": "Reserve a namespace for an owner.",
        "remove": "Withdraw an existing namespace grant.",
        "register": "Register a project after checking its namespace grants.",
        "grandfather": "Register a project with a legacy upload exemption.",
        "check-upload": "Check an upload; conflicts exit with status 3 (409).",
        "list": "List grants in sorted namespace order.",
        "dump": "Print the store, or JSON metadata for --project.",
        "show": "Show a grant's owner, parent and direct children.",
    }
    for name, description in descriptions.items():
        command = commands.add_parser(name, help=description,
                                      description=description)
        _common_options(command)
        if name in {"reserve", "remove", "show"}:
            command.add_argument("namespace", help="package namespace name")
        elif name in {"register", "grandfather", "check-upload"}:
            command.add_argument("name", metavar="project",
                                 help="package project name")
        if name in {"reserve", "register", "grandfather", "check-upload"}:
            command.add_argument("--owner", default=argparse.SUPPRESS,
                                 help="non-empty grant holder or project owner")
        if name == "dump":
            command.add_argument("--project", default=argparse.SUPPRESS,
                                 help="print metadata for one project")
    return parser


def _run(args):
    index = _load(args.store)
    command = args.command
    changed = False
    if command == "reserve":
        grant = index.store.reserve(args.namespace, args.owner)
        result = {"name": grant.name, "owner": grant.owner}
        message = f"reserved {grant.name} for {grant.owner}"
        changed = True
    elif command == "remove":
        grant = index.store.remove(args.namespace)
        result = {"name": grant.name}
        message = f"removed {grant.name}"
        changed = True
    elif command in {"register", "grandfather"}:
        name = _normalize_namespace(args.name)
        owner = _validate_owner(args.owner)
        index.register_project(name, owner,
                               grandfathered=command == "grandfather")
        result = index.project_detail(name)
        message = (f"grandfathered {name}" if command == "grandfather"
                   else f"registered {name} for {owner}")
        changed = True
    elif command == "check-upload":
        name = _normalize_namespace(args.name)
        authorize_upload(name, args.owner, index.store, index.grandfathered)
        result = {"name": name, "allowed": True}
        message = f"OK {name}"
    elif command == "list":
        result = [{"name": grant.name, "owner": grant.owner}
                  for grant in index.store]
        message = "\n".join(f"{grant.name} {grant.owner}"
                            for grant in index.store)
    elif command == "show":
        result = index.namespace_detail(args.namespace)
        parent = result["parent"] or "none"
        children = ", ".join(result["children"]) or "none"
        message = (f"name: {result['name']}\nowner: {result['owner']}\n"
                   f"parent: {parent}\nchildren: {children}")
    else:  # dump
        result = (index.project_detail(args.project) if args.project is not None
                  else _document(index))
        message = json.dumps(result, indent=2, sort_keys=True)
    if changed:
        _save(args.store, index)
    if args.json:
        print(json.dumps(result, sort_keys=True))
    elif message:
        print(message)
    return 0


def main(argv=None):
    """Run an argument vector and return its exit status.

    Status 0 means success, 1 a store or validation error, 2 an argument
    syntax error, and CONFLICT_EXIT (3) an upload conflict.
    """
    try:
        args = _parser().parse_args(argv)
    except SystemExit as exc:
        return exc.code
    try:
        return _run(args)
    except UploadConflictError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return CONFLICT_EXIT
    except (OSError, ValueError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1

