"""Repository state and PEP 752 JSON Simple API metadata."""

from html import escape

from .grants import (
    GrantStore, UnknownGrantError, _normalize_namespace, _validate_owner,
)
from .uploads import GrandfatheredRegistry, authorize_upload

__all__ = [
    "API_VERSION", "LEGACY_API_VERSION", "NotSupportedError", "RepositoryIndex",
]

API_VERSION = "1.5"
LEGACY_API_VERSION = "1.4"


class NotSupportedError(ValueError):
    """The repository does not expose namespace metadata."""


class RepositoryIndex:
    """Manage projects and grants for one repository, without network access."""

    def __init__(self, store=None, *, supports_namespaces=True,
                 grandfathered=None):
        self.store = GrantStore() if store is None else store
        self.supports_namespaces = supports_namespaces
        self.grandfathered = (GrandfatheredRegistry() if grandfathered is None
                              else grandfathered)
        self._projects = {}

    @property
    def api_version(self):
        """The repository's advertised JSON Simple API version."""
        return API_VERSION if self.supports_namespaces else LEGACY_API_VERSION

    def register_project(self, project, owner, *, grandfathered=False):
        """Record a project after authorizing it, or explicitly grandfather it."""
        project = _normalize_namespace(project)
        owner = _validate_owner(owner)
        if grandfathered:
            self.grandfathered.add(project)
        if self.supports_namespaces:
            authorize_upload(project, owner, self.store, self.grandfathered)
        self._projects[project] = owner

    def project_owner(self, project):
        """Return the registered owner, or None for an unknown project."""
        return self._projects.get(_normalize_namespace(project))

    def projects(self):
        """Return a name-sorted copy of the project-to-owner mapping."""
        return dict(sorted(self._projects.items()))

    def project_detail(self, project):
        """Return project metadata, including current matching grants."""
        project = _normalize_namespace(project)
        detail = {"name": project}
        if self.supports_namespaces:
            owner = self.project_owner(project)
            matches = [{"name": grant.name, "owned": grant.owner == owner}
                       for grant in self.store.matching(project)]
            detail["namespaces"] = matches or None
        return detail

    def _require_support(self):
        if not self.supports_namespaces:
            raise NotSupportedError("repository does not support namespaces")

    def list_namespaces(self):
        """Return the /namespaces response with the API version."""
        self._require_support()
        return {"api_version": self.api_version,
                "namespaces": [{"name": name}
                               for name in self.store.namespaces()]}

    def namespace_detail(self, namespace):
        """Return /namespace/<namespace> metadata with direct relationships."""
        self._require_support()
        grant = self.store.get(namespace)
        if grant is None:
            raise UnknownGrantError(f"unknown grant: {namespace!r}")
        return {"name": grant.name, "parent": self.store.parent(grant.name),
                "children": self.store.children(grant.name),
                "owner": grant.owner}

    def simple_html(self, project, files=()):
        """Render escaped HTML Simple API links without namespace metadata."""
        project = escape(_normalize_namespace(project))
        lines = ["<!DOCTYPE html>", "<html><head>",
                 f"<title>Links for {project}</title>", "</head><body>",
                 f"<h1>Links for {project}</h1>"]
        for file in files:
            url = escape(file["url"], quote=True)
            filename = escape(file["filename"])
            lines.append(f'<a href="{url}">{filename}</a><br>')
        lines.append("</body></html>")
        return "\n".join(lines) + "\n"

