"""Upload authorization and explicit exceptions for existing projects."""

from .grants import _normalize_namespace, _validate_owner
from .normalize import is_valid_namespace, normalize_name

__all__ = [
    "CONFLICT_STATUS", "UploadConflictError", "GrandfatheredRegistry",
    "authorize_upload",
]

CONFLICT_STATUS = 409


class UploadConflictError(ValueError):
    """An upload conflicts with an active namespace grant."""

    status_code = CONFLICT_STATUS

    def __init__(self, project, namespace, owner):
        self.project = _normalize_namespace(project)
        self.namespace = _normalize_namespace(namespace)
        self.owner = owner
        super().__init__(
            f"409 Conflict: {self.project!r} matches namespace "
            f"{self.namespace!r} owned by {owner!r}"
        )


class GrandfatheredRegistry:
    """Track exact project names exempt from namespace upload restrictions."""

    def __init__(self, projects=()):
        self._projects = set()
        for project in projects:
            self.add(project)

    def __len__(self):
        return len(self._projects)

    def __contains__(self, project):
        return (is_valid_namespace(project)
                and normalize_name(project) in self._projects)

    def add(self, project):
        """Exempt the normalized project name."""
        self._projects.add(_normalize_namespace(project))

    def discard(self, project):
        """Remove a project's exemption if present."""
        self._projects.discard(_normalize_namespace(project))

    def covers(self, project):
        """Return whether this exact normalized project is exempt."""
        return _normalize_namespace(project) in self._projects

    def projects(self):
        """Return sorted exempt project names."""
        return sorted(self._projects)


def authorize_upload(project, owner, store, grandfathered=None):
    """Return True, or raise UploadConflictError for another owner's grant.

    Explicit grandfathering exempts only the named project, not its prefix.
    """
    project = _normalize_namespace(project)
    owner = _validate_owner(owner)
    if grandfathered is not None and grandfathered.covers(project):
        return True
    for grant in store.matching(project):
        if grant.owner != owner:
            raise UploadConflictError(project, grant.name, grant.owner)
    return True

